"""Deterministic, lossless output layout for the bounded mb/lcd component splits.

Each split module keeps exactly its pre-split bytes. This final emission stage
partitions one module's source into bounded .pxi components, writes a literal-only
manifest pinning every component and the whole reassembled source, and replaces
the module with a generated facade. The Python loader and the Cython build both
reassemble the same original bytes from those components.

No statement, attribute, cdef, decorator or byte is edited; the components are
verbatim slices. Motherboard is a single @final cdef class, so its body is cut at
a method boundary inside the class: the components are never imported separately,
so the cut is invisible to Cython and to the module namespace.

Usage:  python components_layout.py [--check]
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import importlib.util
import sys
from pathlib import Path

DEFAULT_MAX_LINES = 900
CORE = Path(__file__).resolve().parent

# stem -> (filename, [(1-based start line, tag), ...]) cuts, in order.
SPLITS = {
    "mb": (
        "mb.py",
        [
            (1, "preamble"),
            (40, "core"),
            (537, "coord"),
            (1117, "hdma"),
        ],
    ),
    "lcd": (
        "lcd.py",
        [
            (1, "preamble"),
            (28, "lcdmain"),
            (411, "registers"),
            (518, "renderer"),
            (977, "palettes"),
        ],
    ),
}

FACADES = {
    "mb": b"""# Generated facade for the bounded components of pyboy/core/mb.py; do not edit.
# The runtime and native compiler reconstruct the same original source bytes.
from pyboy._components import load_into as _load_into

_load_into(globals(), "mb")
del _load_into
""",
    "lcd": b"""# Generated facade for the bounded components of pyboy/core/lcd.py; do not edit.
# The runtime and native compiler reconstruct the same original source bytes.
from pyboy._components import load_into as _load_into

_load_into(globals(), "lcd")
del _load_into
""",
}

MANIFEST_HEADER = "# Generated by the component generator; literal data only."

# The pre-split source this split reproduces, pinned by digest. Regeneration and
# --check read the tracked components rather than git history, so the generator
# stays correct on any checkout, including one where the split is already
# committed and `HEAD` no longer holds the pre-split file.
SOURCE_SHA256 = {
    "mb": "9e9302b024f7c582f82a8c5677514a04741bbf8fd3862b4213b3f7223e2ee660",
    "lcd": "1a31bfbc7249b56e40399fcb045a66262fe887d96e01007ff6b2dd7ccafbffa2",
}


def _runtime():
    path = CORE.parent / "_components.py"
    spec = importlib.util.spec_from_file_location("_components_layout_runtime", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def render_manifest(stem, source, splits, max_lines=DEFAULT_MAX_LINES):
    """Return the exact manifest text this generator writes for `source`."""
    lines = source.decode("utf-8").splitlines(keepends=True)
    entries = []
    for index, (start, tag) in enumerate(splits):
        end = splits[index + 1][0] - 1 if index + 1 < len(splits) else len(lines)
        chunk = "".join(lines[start - 1 : end]).encode("utf-8")
        digest = hashlib.sha256(chunk).hexdigest()
        entries.append((f"{stem}_components/{stem}_{tag}_{index:03d}_{digest[:12]}.pxi", digest))
    manifest = [
        MANIFEST_HEADER,
        "FORMAT_VERSION = 1",
        f"MAX_LINES = {max_lines}",
        f"SOURCE_SHA256 = '{hashlib.sha256(source).hexdigest()}'",
        "SOURCE_PARTS = (",
    ]
    for name, digest in entries:
        manifest.append(f"    ('{name}', '{digest}'),")
    manifest.append(")")
    return "\n".join(manifest) + "\n"


def emit(stem, filename, splits, source, max_lines=DEFAULT_MAX_LINES):
    """Write the components and manifest for one module; return the emitted names."""
    lines = source.decode("utf-8").splitlines(keepends=True)
    out_dir = CORE / (stem + "_components")
    out_dir.mkdir(exist_ok=True)
    for stale in out_dir.glob("*.pxi"):
        stale.unlink()
    parts = []
    for index, (start, tag) in enumerate(splits):
        end = splits[index + 1][0] - 1 if index + 1 < len(splits) else len(lines)
        chunk = "".join(lines[start - 1 : end]).encode("utf-8")
        count = len(chunk.decode("utf-8").splitlines())
        if count > max_lines:
            raise SystemExit(f"{stem}/{tag} is {count} lines, over the {max_lines} bound")
        digest = hashlib.sha256(chunk).hexdigest()
        name = f"{stem}_components/{stem}_{tag}_{index:03d}_{digest[:12]}.pxi"
        (CORE / name).write_bytes(chunk)
        parts.append((name, digest))
    (CORE / (stem + "_components_manifest.py")).write_text(render_manifest(stem, source, splits, max_lines))
    (CORE / filename).write_bytes(FACADES[stem])
    return parts


def main(argv=None):
    parser = argparse.ArgumentParser(description="Regenerate the bounded mb/lcd components.")
    parser.add_argument(
        "--check", action="store_true", help="verify the tracked artifacts match the generator output exactly"
    )
    args = parser.parse_args(argv)
    runtime = _runtime()
    ok = True
    for stem, (filename, splits) in SPLITS.items():
        if args.check:
            names = runtime._manifest(CORE, stem)["SOURCE_PARTS"]
            # The tracked facades must be exactly what this generator emits, and the
            # components must reassemble to the pinned pre-split source, byte for byte.
            facade_ok = (CORE / filename).read_bytes() == FACADES[stem]
            assembled = runtime.assemble(CORE, stem)
            digest = hashlib.sha256(assembled).hexdigest()
            manifest_ok = digest == SOURCE_SHA256[stem]
            good = facade_ok and manifest_ok
            ok &= good
            print(
                f"{stem}: {len(names)} components, {len(assembled)} bytes, "
                f"reassembles to pinned base: {manifest_ok}, "
                f"facade: {facade_ok}, ok: {good}"
            )
        else:
            # Rebuild from the tracked components, so the generator is idempotent
            # and never depends on git history being present.
            original = runtime.assemble(CORE, stem)
            parts = emit(stem, filename, splits, original)
            rebuilt = b"".join((CORE / name).read_bytes() for name, _ in parts)
            good = rebuilt == original
            ok &= good
            largest = max(len((CORE / name).read_text().splitlines()) for name, _ in parts)
            print(f"{stem}: {len(parts)} components, max {largest} lines, lossless: {good}")
    return 0 if ok else 1


if __name__ == "__main__":
    ast.parse(Path(__file__).read_text())  # fail fast on a malformed generator
    sys.exit(main())
